def transform(grid):
    out = [row[:] for row in grid]
    H, W = len(grid), len(grid[0])
    background = max(range(10), key=lambda x: sum(r.count(x) for r in grid))

    def cuts(length, empty):
        result, start = [], None
        for i in range(length + 1):
            if i == length or empty(i):
                if start is not None:
                    result.append((start, i))
                    start = None
            elif start is None:
                start = i
        return result

    rows = cuts(H, lambda r: all(v == background for v in grid[r]))
    cols = cuts(W, lambda c: all(grid[r][c] == background for r in range(H)))
    if len(rows) == 1:
        cols = [(0, W)]

    for top, bottom in rows:
        for left, right in cols:
            top, bottom = top + 1, bottom - 1
            left, right = left + 1, right - 1
            height, width = bottom - top, right - left
            if height <= 0 or width <= 0:
                continue
            choices = []
            for ph in range(1, height + 1):
                for pw in range(1, width + 1):
                    counts = [[{} for _ in range(pw)] for _ in range(ph)]
                    for i in range(height):
                        for j in range(width):
                            value = grid[top + i][left + j]
                            counts[i % ph][j % pw][value] = counts[i % ph][j % pw].get(value, 0) + 1
                    motif = [[max(d, key=d.get) for d in line] for line in counts]
                    errors = sum(grid[top+i][left+j] != motif[i % ph][j % pw]
                                 for i in range(height) for j in range(width))
                    choices.append((errors, ph * pw, ph, pw, motif))
            errors, _, ph, pw, motif = min(choices, key=lambda x: (x[0], x[1]))
            for i in range(height):
                for j in range(width):
                    out[top+i][left+j] = motif[i % ph][j % pw]
    return out
