def transform(grid):
    original = grid
    result = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = max(set(sum(grid, [])), key=sum(grid, []).count)

    def runs(length, is_separator):
        answer = []
        i = 0
        while i < length:
            if is_separator(i):
                i += 1
                continue
            j = i
            while j < length and not is_separator(j):
                j += 1
            answer.append((i, j))
            i = j
        return answer

    row_runs = runs(h, lambda r: all(x == background for x in grid[r]))
    col_runs = runs(w, lambda c: all(grid[r][c] == background for r in range(h)))
    if len(row_runs) == 1:
        col_runs = [(0, w)]

    for rt, rb in row_runs:
        for cl, cr in col_runs:
            rt, rb, cl, cr = rt + 1, rb - 1, cl + 1, cr - 1
            ph, pw = rb - rt, cr - cl
            best_key = None
            best_tile = None
            for th in range(1, ph + 1):
                for tw in range(1, pw + 1):
                    tile = []
                    mismatches = 0
                    for i in range(th):
                        line = []
                        for j in range(tw):
                            values = [original[rt + k][cl + l]
                                      for k in range(i, ph, th)
                                      for l in range(j, pw, tw)]
                            counts = {v: values.count(v) for v in set(values)}
                            value = max(counts, key=counts.get)
                            line.append(value)
                            mismatches += len(values) - counts[value]
                        tile.append(line)
                    key = (mismatches, th * tw)
                    if best_key is None or key < best_key:
                        best_key, best_tile = key, (th, tw, tile)
            th, tw, tile = best_tile
            for i in range(ph):
                for j in range(pw):
                    result[rt + i][cl + j] = tile[i % th][j % tw]
    return result
